package io.github.polestarcn.companion;
import static org.junit.Assert.*;
import android.app.*;import android.widget.*;import android.view.*;import android.content.*;
import java.lang.reflect.*;import java.util.*;
import io.github.polestarcn.companion.api.ProtoWire;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28)
public class V084RegressionTest {
 private AppRegressionTest base;private MainActivity a;private VehicleCoordinator model;
 @Before public void start()throws Exception{base=new AppRegressionTest();base.start();Field f=AppRegressionTest.class.getDeclaredField("activity");f.setAccessible(true);a=(MainActivity)f.get(base);model=VehicleCoordinator.get(a);}
 @After public void stop(){AlertDialog d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();if(d!=null)d.dismiss();base.stop();}
 private Map<Integer,Object> reply(int actual,int pending){return ProtoWire.decode(ProtoWire.concat(ProtoWire.bytesField(3,ProtoWire.varintField(1,actual)),ProtoWire.bytesField(4,ProtoWire.varintField(1,pending))));}
 @Test public void chargeLimitUsesConfirmedFieldNotPendingOrSoc(){ChargingSnapshot v=ChargingSnapshot.unknown().withTarget(reply(80,90));assertEquals(Integer.valueOf(80),v.targetPercent);assertNull(ChargingSnapshot.unknown().withTarget(reply(101,80)).targetPercent);assertNull(ChargingSnapshot.unknown().withTarget(reply(0,80)).targetPercent);assertNull(ChargingSnapshot.unknown().withTarget(Collections.emptyMap()).targetPercent);}
 @Test public void cacheKeepsChargeLimitAndOwnTimestamp(){long now=System.currentTimeMillis();Map<Integer,Object> reply=ProtoWire.decode(ProtoWire.bytesField(3,ProtoWire.concat(ProtoWire.varintField(1,90),ProtoWire.varintField(3,now))));VehicleSnapshot v=new VehicleSnapshot("test","masked",50,200,10000,"空闲","全部关闭","全部关闭","已关闭","已锁",now,"LIVE",false,"关闭","关闭").withCharging(ChargingSnapshot.unknown().withTarget(reply));VehicleSnapshotStore.saveChina(a,v);VehicleSnapshot saved=VehicleSnapshotStore.loadChina(a);assertEquals("90%",DisplayMetric.CHARGE_LIMIT.value(a,saved,true,false));assertEquals(now,DisplayMetric.CHARGE_LIMIT.reportedAt(saved));}
 @Test public void serviceCycleUsesEarlierLimitAndHandlesMissingValues(){assertEquals(30000,ServiceReading.REFERENCE_KM);assertNull(ServiceReading.cyclePercent(a,null));VehicleSnapshot v=new VehicleSnapshot("test","masked",50,200,10000,"空闲","全部关闭","全部关闭","已关闭","已锁",1,"LIVE",false,"关闭","关闭");v=v.withHealth(new VehicleHealthSnapshot(1,1,1,1,1,1,1,1,1,931,75,14959));assertEquals(Integer.valueOf(21),ServiceReading.cyclePercent(a,v));v=v.withHealth(new VehicleHealthSnapshot(1,1,1,1,1,1,1,1,1,null,null,15000));assertEquals(Integer.valueOf(50),ServiceReading.cyclePercent(a,v));}
 @Test public void consentStartsUncheckedCannotAcceptByDismissAndPersistsOnlyOnClick(){a.getSharedPreferences("legal",0).edit().clear().commit();int[] calls={0};FirstUseConsent.show(a,()->calls[0]++);AlertDialog d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();assertFalse(d.getButton(-1).isEnabled());CheckBox box=d.findViewById(android.R.id.content).findViewWithTag("legal_accept");assertFalse(box.isChecked());assertFalse(FirstUseConsent.accepted(a));box.setChecked(true);assertTrue(d.getButton(-1).isEnabled());assertFalse(FirstUseConsent.accepted(a));d.getButton(-1).performClick();assertTrue(FirstUseConsent.accepted(a));assertEquals(1,calls[0]);}
 @Test public void decliningConsentDoesNotPersist(){a.getSharedPreferences("legal",0).edit().clear().commit();FirstUseConsent.show(a,()->fail("declined"));AlertDialog d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();d.getButton(-2).performClick();assertFalse(FirstUseConsent.accepted(a));}
 @Test public void readbackProgressTickDoesNotRebuildSettings()throws Exception{Field f=VehicleCoordinator.class.getDeclaredField("signedIn");f.setAccessible(true);f.setBoolean(model,true);f=MainActivity.class.getDeclaredField("page");f.setAccessible(true);f.setInt(a,2);Method render=MainActivity.class.getDeclaredMethod("render");render.setAccessible(true);render.invoke(a);View content=a.findViewById(android.R.id.content);View before=((ViewGroup)content).getChildAt(0);model.commandPending=true;model.progressOnly=true;Method changed=MainActivity.class.getDeclaredMethod("onModelChanged");changed.setAccessible(true);changed.invoke(a);assertSame(before,((ViewGroup)content).getChildAt(0));model.commandPending=false;model.progressOnly=false;}
 @Test public void locksKeepStateGlyphsAndTrunkUsesApprovedGlyph()throws Exception{Method m=MainActivity.class.getDeclaredMethod("controlIcon",String.class,String.class);m.setAccessible(true);assertEquals(R.drawable.ic_lock,m.invoke(a,"lock","已上锁"));assertEquals(R.drawable.ic_unlock,m.invoke(a,"lock","未锁"));assertEquals(R.drawable.ic_tailgate_detail,m.invoke(a,"trunk","已关闭"));assertEquals(R.drawable.ic_tailgate_detail,m.invoke(a,"trunk","已打开"));}
}
